using System.Collections.Generic;
using UnityEngine;
namespace NakiLegend.Prototype {
 public sealed partial class NakiPrototype {
  private sealed class ForgeVolley {public Enemy owner;public Vector2 aim;public float when;public GameObject warning;}
  private readonly List<ForgeVolley> forgeVolleys=new List<ForgeVolley>();
  private GameObject emberRingVisual;private Vector2 emberRingAt;private float emberRingBorn;
  private readonly HashSet<Enemy> emberVictims=new HashSet<Enemy>();
  private static bool IsWorkshopEnemy(EnemyKind kind){return kind>=EnemyKind.ForgeGuard&&kind<=EnemyKind.ForgeMold;}
  private void ConfigureWorkshopEnemy(Enemy e){e.boss=e.kind==EnemyKind.ForgeMaster;e.radius=e.boss?.95f:e.kind==EnemyKind.MoltenCrab?.45f:.38f;e.hp=e.maximum=e.boss?1520:e.kind==EnemyKind.FurnaceCore?158:e.kind==EnemyKind.MoltenCrab?142:e.kind==EnemyKind.ForgeMold?85:126;e.speed=e.boss?.95f:e.kind==EnemyKind.FurnaceCore?.7f:1.25f;e.affinity=e.attackElement=Element.Fire;e.iceArmor=e.boss?3:e.kind==EnemyKind.MoltenCrab?2:0;e.soulEligible=e.kind==EnemyKind.ForgeGuard||e.kind==EnemyKind.MoltenCrab;e.nextAttack=clock+1.5f;}
  private GameObject ForgeFanWarning(Enemy e,Vector2 aim,int count,float spacing){return EnemyMuzzleTell(e.position,aim);}

  private GameObject ForgeWarning(Enemy e){int move=e.attackNumber%3;if(e.boss&&move==0)return WarningCircle(e.strikePoint,1.2f);if(e.kind==EnemyKind.ForgeGuard||e.kind==EnemyKind.MoltenCrab||e.boss&&move==1)return ChapterLineWarning(e.position,e.attackDirection,e.boss?5.5f:3,e.boss?1.1f:.65f);return ForgeFanWarning(e,e.attackDirection,e.boss?(e.secondPhase?12:8)+LivingForgeMolds()*2:5,e.boss?(e.secondPhase?13:15):18);}
  private void PoseWorkshopEnemy(Enemy e,Vector2 old,float dt){e.velocity=dt>0?(e.position-old)/dt:Vector2.zero;e.root.transform.position=e.position;e.body.flipX=(e.windup>0?e.attackDirection:position-e.position).x<0;e.body.sortingOrder=DepthAt(e.position.y);e.body.color=clock<e.hurtUntil?C("ffe0bf"):e.boss&&clock<e.recoveryUntil?C("ffd8a6"):clock<e.iceSlowUntil?C("b9eaff"):Color.white;if(e.shadow!=null)e.shadow.transform.position=e.position;}
  private void UpdateWorkshopEnemy(Enemy e,float dt){Vector2 old=e.position;if(e.kind==EnemyKind.ForgeMold){PoseWorkshopEnemy(e,old,dt);return;}RecoverIceFooting(e);if(e.boss&&!e.secondPhase&&e.hp<e.maximum*.7f){e.secondPhase=true;e.windup=0;if(e.warning!=null)Destroy(e.warning);e.recoveryUntil=clock+1.4f;e.nextAttack=clock+1.6f;AddFloatingHit("炉芯升温 · 留意铸模折射",e.position+Vector2.up*2,C("ffd39a"));}
   if(e.chargeUntil>0){if(clock<e.chargeUntil){e.position=MoveEnemyCharge(e,e.attackDirection*4.5f*dt);if(DistanceToSegment(position,old,e.position)<e.radius+.28f&&!ProjectilePathBlocked(e.position,position,.04f))TakeJourneyDamage(1.5f,Element.Fire);}else{e.chargeUntil=0;e.recoveryUntil=clock+1;}}
   else if(e.windup>0){e.windup-=dt;if(e.windup<=0){if(e.warning!=null)Destroy(e.warning);ResolveWorkshopMove(e);}}
   else if(clock>=e.recoveryUntil){Vector2 to=position-e.position;bool visible=!ProjectilePathBlocked(e.position,position,.1f);float range=e.boss?9:e.kind==EnemyKind.FurnaceCore?7:3.1f;if(clock>=e.nextAttack&&visible&&to.magnitude<range){e.attackNumber++;e.attackDirection=to.sqrMagnitude>.01f?to.normalized:Vector2.down;e.strikePoint=position;e.windup=e.boss?1.15f:.9f;e.nextAttack=clock+e.windup+(e.boss?(e.secondPhase?1.05f:1.4f):1.7f);e.warning=ForgeWarning(e);}else if(!visible||to.magnitude>(e.boss?3.5f:e.kind==EnemyKind.FurnaceCore?4.5f:1.8f))MoveIcePursuit(e,e.speed*(clock<e.iceSlowUntil?.6f:1)*dt);}
   PoseWorkshopEnemy(e,old,dt);
  }
  private int LivingForgeMolds(){int count=0;foreach(Enemy mold in enemies)if(mold.kind==EnemyKind.ForgeMold&&mold.hp>0)count++;return count;}
  private void ResolveWorkshopMove(Enemy e){e.recoveryUntil=clock+(e.boss?1.4f:.85f);if(e.kind==EnemyKind.ForgeGuard){if(DistanceToSegment(position,e.position,e.position+e.attackDirection*3)<.6f&&!ProjectilePathBlocked(e.position,position,.04f))TakeJourneyDamage(1.5f,Element.Fire);return;}if(e.kind==EnemyKind.MoltenCrab){e.chargeUntil=clock+.45f;return;}if(e.kind==EnemyKind.FurnaceCore){FireFan(e,5,18,4.3f);return;}if(!e.boss)return;
   int move=e.attackNumber%3;if(move==0){QueueFireBomb(e.strikePoint,.65f,1.15f);Vector2 side=new Vector2(-e.attackDirection.y,e.attackDirection.x);QueueFireBomb(FindFreeInteractionPoint(e.strikePoint+side*1.8f),.95f,.8f);QueueFireBomb(FindFreeInteractionPoint(e.strikePoint-side*1.8f),1.25f,.8f);}
   else if(move==1){if(DistanceToSegment(position,e.position,e.position+e.attackDirection*5.5f)<.7f&&!ProjectilePathBlocked(e.position,position,.04f))TakeJourneyDamage(2,Element.Fire);Enemy nearest=null;foreach(Enemy mold in enemies)if(mold.kind==EnemyKind.ForgeMold&&mold.hp>0&&(nearest==null||Vector2.Distance(mold.position,e.position)<Vector2.Distance(nearest.position,e.position)))nearest=mold;if(nearest!=null){Vector2 pulled=NearestSafeFooting(e.position+e.attackDirection*3);nearest.position=pulled;nearest.root.transform.position=pulled;SpellSpark(pulled,C("ffcda6"),.4f);}if(e.secondPhase)FireFan(e,7,17,3.8f);}
   else{FireFan(e,(e.secondPhase?12:8)+LivingForgeMolds()*2,e.secondPhase?13:15,4.3f);if(e.secondPhase)QueueForgeMoldVolleys();}
  }
  private void QueueForgeMoldVolleys(){foreach(Enemy mold in enemies)if(mold.kind==EnemyKind.ForgeMold&&mold.hp>0){Vector2 aim=(position-mold.position).normalized;forgeVolleys.Add(new ForgeVolley{owner=mold,aim=aim,when=clock+.8f,warning=ForgeFanWarning(mold,aim,4,14)});}}
  private void TickWorkshopEffects(){for(int i=forgeVolleys.Count-1;i>=0;i--){var v=forgeVolleys[i];if(v.owner.hp<=0||!enemies.Contains(v.owner)){if(v.warning!=null)Destroy(v.warning);forgeVolleys.RemoveAt(i);continue;}if(clock<v.when)continue;if(v.warning!=null)Destroy(v.warning);v.owner.attackDirection=v.aim;FireFan(v.owner,4,14,3.8f);forgeVolleys.RemoveAt(i);}
   if(emberRingVisual==null)return;float t=(clock-emberRingBorn)/.35f;if(t>=1){Destroy(emberRingVisual);emberRingVisual=null;emberVictims.Clear();return;}float r=Mathf.Lerp(.2f,2.1f,t);emberRingVisual.transform.localScale=Vector3.one*r*2;emberRingVisual.GetComponent<SpriteRenderer>().color=new Color(1,.57f,.27f,1-t*.7f);DispelProjectiles(emberRingAt,r);if(woodlandMode)BurnWoodZones(emberRingAt,emberRingAt,r);foreach(Enemy e in new List<Enemy>(enemies))if(e.hp>0&&!emberVictims.Contains(e)&&Vector2.Distance(e.position,emberRingAt)<r+e.radius&&!ProjectilePathBlocked(emberRingAt,e.position,.03f)){emberVictims.Add(e);ApplyElementDamage(e,SkillDamage(18),Element.Fire);}
  }
  private void ClearWorkshopEffects(){foreach(var v in forgeVolleys)if(v.warning!=null)Destroy(v.warning);forgeVolleys.Clear();if(emberRingVisual!=null)Destroy(emberRingVisual);emberRingVisual=null;emberVictims.Clear();}
  private void CastEmberRing(){if(!emberRingKnown){JourneyHint("先找到炉匠阿铎，学习控制火焰的边界");return;}if(clock<emberRingReady||clock<dashUntil||!SpendSkillPower(12))return;emberRingReady=clock+5;emberRingBorn=clock;emberRingAt=position;emberVictims.Clear();if(emberRingVisual!=null)Destroy(emberRingVisual);emberRingVisual=Draw("Brief ember boundary",windRingSprite??disc,position,Vector2.one*.4f,C("ffae65"),800);DispelProjectiles(position,.2f);castDirection=facing;castPoseUntil=clock+.3f;SkillSound("meteor","hit");}
 }
}
